// Wrap the generated sections in the shared envelope (schema: content-generation.schema.json).
// Only keep sections that were requested AND came back non-empty; record which ones for traceability.
const trig = $('Execute Workflow Trigger').first().json;
const out = $input.first().json.output || {};
const want = ($('Plan Sections').first().json.want) || ['alcance_tecnico', 'resumen_comercial'];
let grounded = [];
try { grounded = $('Aggregate Grounding').first().json.grounded_on || []; } catch (e) {}

const data = { grounded_on: grounded, sections_generated: [] };
for (const key of want) {
  const val = (out[key] || '').toString().trim();
  if (val) { data[key] = val; data.sections_generated.push(key); }
}
// Safety net: the two core sections must always be present.
if (!data.alcance_tecnico) data.alcance_tecnico = (out.alcance_tecnico || '').toString().trim() || 'Scope to be detailed.';
if (!data.resumen_comercial) data.resumen_comercial = (out.resumen_comercial || '').toString().trim() || 'Commercial summary to be detailed.';

return [{ json: {
  client_id: trig.client_id,
  client_config: trig.client_config || null,
  status: 'ok',
  errors: [],
  data
} }];
